export function getCountyBySlug(stateSlug: string, countySlug: string): CountyData | undefined {
  const stateData = stateCountyData.find(s => s.stateSlug === stateSlug);
  return stateData?.counties.find(c => c.slug === countySlug);
}

export function getStateCounties(stateSlug: string): CountyData[] {
  return stateCountyData.find(s => s.stateSlug === stateSlug)?.counties || [];
}

export function getAllCountySlugs(): { stateSlug: string; countySlug: string }[] {
  const slugs: { stateSlug: string; countySlug: string }[] = [];
  for (const state of stateCountyData) {
    for (const county of state.counties) {
      slugs.push({ stateSlug: state.stateSlug, countySlug: county.slug });
    }
  }
  return slugs;
}
